static Score make_score(int type, const vector<int>& vals) {
    Score s;
    s.type = type;
    for (int v : vals) s.key = s.key * 20 + v;
    return s;
}

static bool less_score(const Score& a, const Score& b) {
    if (a.type != b.type) return a.type < b.type;
    return a.key < b.key;
}

